UPDATE gm.products SET source_record='{"id":"parlante-jbl-go-essential-2-modelo-2026-tipo-c-ipx7-5-hs-pot-29","nombre":"Parlante Jbl Go Essential 2 Modelo 2026 Tipo C Ipx7 5 Hs Potencia 3,1W","categoria":"Audio","descripcion":"Disfrutá de tu música donde quieras con el JBL GO Essential 2, un parlante Bluetooth portátil ultracompacto que combina practicidad, potencia y el reconocido sonido JBL Pro Original. Su diseño liviano y moderno lo hace ideal para acompañarte en todo momento, ya sea en casa, reuniones, viajes o actividades al aire libre. Conectá tu smartphone, tablet u otros dispositivos vía Bluetooth y reproducí tu música favorita de forma inalámbrica con una autonomía de hasta 5 horas. Además, su certificación IPX7 resistente al agua permite usarlo con tranquilidad cerca de la pileta, en la playa o incluso bajo la lluvia. Disponible en distintos colores vibrantes, el JBL GO Essential ofrece un sonido sorprendente en un tamaño compacto, convirtiéndose en el compañero perfecto para llevar la música a todas partes.","embalaje":"CAJA X 12","precio_pesos":60924,"precio_usd":40.62,"variantes":[{"color":"AZUL","codigo":3030,"precio_pesos":60924,"precio_usd":40.62,"imagenes":["images/3030_0.jpg","images/3030_1.jpg"],"precios_anteriores_json":{"precio_pesos":60548,"precio_usd":40.37},"stock_disponible":true,"estado_actualizacion":"coincidencia","fuente_actualizacion":[{"archivo":"importacion.xlsx","hoja":"Table 4","celda_codigo":"C49","color":"FFC3D69A","celdas_precios":{"precio_pesos":"C52","precio_usd":"C55"}}]},{"color":"ROJO","codigo":3031,"precio_pesos":60924,"precio_usd":40.62,"imagenes":["images/3031_0.jpg","images/3031_1.jpg","images/3031_2.jpg","images/3031_3.jpg"],"precios_anteriores_json":{"precio_pesos":60548,"precio_usd":40.37},"stock_disponible":true,"estado_actualizacion":"coincidencia","fuente_actualizacion":[{"archivo":"importacion.xlsx","hoja":"Table 4","celda_codigo":"C61","color":"FFC3D69A","celdas_precios":{"precio_pesos":"C64","precio_usd":"C67"}