UPDATE gm.products SET source_record='{"id":"cargador-de-bateria-noga-dt-6a-12v-auto-moto-intelitenge-5-modos-de-carga-lista-1582","nombre":"CARGADOR DE BATERIA NOGA DT-6A 12v AUTO MOTO INTELITENGE 5 MODOS DE CARGA","categoria":"Cargadores y Energía","descripcion":"El Noga DT-6A es un cargador inteligente diseñado para cargar y mantener baterías de 12V de forma automática, segura y eficiente. Gracias a su control por microprocesador, optimiza cada etapa de la carga prolongando la vida útil de la batería y evitando sobrecargas. Su sistema inteligente detecta el estado de la batería y ajusta automáticamente el voltaje y la corriente para lograr una carga más rápida, estable y segura. Además, incorpora múltiples protecciones contra cortocircuitos, inversión de polaridad, sobrecalentamiento y sobrecarga, garantizando un funcionamiento confiable en todo momento. Ideal para autos, motos, cuatriciclos, embarcaciones y otros vehículos con baterías de plomo-ácido, AGM y GEL. Su funcionamiento totalmente automático y su pantalla digital facilitan el monitoreo del proceso de carga, ofreciendo una solución práctica tanto para uso doméstico como profesional.","embalaje":null,"imagen":"images/1582_0.jpg","variantes":[{"codigo":"1582","color":null,"precio_pesos":23685,"precio_usd":15.79,"stock_disponible":true,"imagenes":["images/1582_0.jpg","images/1582_1.jpg"],"estado_actualizacion":"coincidencia","precios_anteriores_json":{},"fuente_actualizacion":[{"archivo":"importacion.xlsx","hoja":"Table 86","celda_codigo":"C1","color":"FFC3D69A","celdas_precios":{"precio_pesos":"C4","precio_usd":"C7"}}]}],"origen_catalogo":"importacion.xlsx","precio_pesos":23685,"precio_usd":15.79,"stock_disponible":true}'::jsonb WHERE id='f67e6bbb-f6fb-547e-a8a5-099ff0e3970a'::uuid;
