INSERT INTO gm.products (id,source_id,name,description,category_id,packaging_original,primary_image_id,source_record) VALUES ('03e4eed8-360f-5c82-ac64-cee7b5f704d5','cargador-de-bateria-noga-dt-10a-12v-auto-moto-intelitenge-5-modos-de-carga-lista-1583','CARGADOR DE BATERIA NOGA DT-10A 12V AUTO MOTO INTELITENGE 5 MODOS DE CARGA','El Noga DT-10A es un cargador inteligente diseñado para cargar y mantener baterías de 12V de forma automática, segura y eficiente. Gracias a su control por microprocesador, optimiza cada etapa de la carga para prolongar la vida útil de la batería y prevenir sobrecargas. Su sistema inteligente detecta el estado de la batería y ajusta automáticamente el voltaje y la corriente para brindar una carga rápida, estable y confiable. Además, incorpora protección contra cortocircuitos, inversión de polaridad, sobrecalentamiento y sobrecarga, ofreciendo máxima seguridad durante su uso. Ideal para autos, camionetas, SUV, utilitarios, embarcaciones y otros vehículos con baterías de plomo-ácido, AGM y GEL. Su pantalla digital permite controlar el proceso de carga en tiempo real, siendo una excelente opción tanto para uso doméstico como profesional.','79e34200-e56d-5de0-b64b-f481b62434b7',NULL,'99f0e7b0-8000-54c5-92f3-56abe4f17f6e','{"id":"cargador-de-bateria-noga-dt-10a-12v-auto-moto-intelitenge-5-modos-de-carga-lista-1583","nombre":"CARGADOR DE BATERIA NOGA DT-10A 12V AUTO MOTO INTELITENGE 5 MODOS DE CARGA","categoria":"Cargadores y Energía","descripcion":"El Noga DT-10A es un cargador inteligente diseñado para cargar y mantener baterías de 12V de forma automática, segura y eficiente. Gracias a su control por microprocesador, optimiza cada etapa de la carga para prolongar la vida útil de la batería y prevenir sobrecargas. Su sistema inteligente detecta el estado de la batería y ajusta automáticamente el voltaje y la corriente para brindar una carga rápida, estable y confiable. Además, incorpora protección contra cortocircuitos, inversión de polaridad, sobrecalentamiento y sobrecarga, ofreciendo máxima seguridad durante su uso. Ideal para autos, camionetas, SUV, utilitarios, embarcaciones y otros vehículos con baterías de plomo-ácido, AGM y GEL. Su pantalla digital permite controlar el proceso de carga en tiempo real, siendo una excelente opción tanto para uso doméstico como profesional.","embalaje":null,"imagen":"images/1583_0.jpg","variantes":[],"origen_catalogo":"importacion.xlsx"}') ON CONFLICT DO NOTHING;
