INSERT INTO gm.products (id,source_id,name,description,category_id,packaging_original,primary_image_id,source_record) VALUES ('a733c8f9-58e4-52e9-b69f-087b6188df6c','estacion-de-carga-8-en-1-soul-cvj-8en1ne-5-type-c-3-qc-usb-pd65w-qc22-5w-gan-lista-4522','ESTACION DE CARGA 8 EN 1 SOUL CVJ-8EN1NE 5 TYPE C + 3 QC USB PD65W / QC22,5W GaN','Centralizá la energía de todos tus dispositivos en un solo lugar. La estación de carga inteligente Soul CVJ-8EN1NE combina tecnología semiconductora GaN (Nitruro de Galio) de última generación con una potencia total de hasta 65W, permitiéndote cargar notebooks, tablets, smartphones y accesorios de manera ultrarrápida, eficiente y sin sobrecalentamiento. Gracias a sus 8 puertos de salida (5 USB-C y 3 USB-A), es el accesorio ideal para escritorios de trabajo, mesas de noche, oficinas compartidas o viajes, Tecnología GaN Avanzada, Carga Rápida Power Delivery (PD 65W), 8 Dispositivos en Simultáneo, Gestión Inteligente de Energía, Diseño Versátil con base de apoyo vertical, incluye 1x Cable de alimentación de red eléctrica (220V). Compatibilidad Universal Notebooks / Laptops, Smartphones, Tablets, Gadgets & Varios.','79e34200-e56d-5de0-b64b-f481b62434b7',NULL,NULL,'{"id":"estacion-de-carga-8-en-1-soul-cvj-8en1ne-5-type-c-3-qc-usb-pd65w-qc22-5w-gan-lista-4522","nombre":"ESTACION DE CARGA 8 EN 1 SOUL CVJ-8EN1NE 5 TYPE C + 3 QC USB PD65W / QC22,5W GaN","categoria":"Cargadores y Energía","descripcion":"Centralizá la energía de todos tus dispositivos en un solo lugar. La estación de carga inteligente Soul CVJ-8EN1NE combina tecnología semiconductora GaN (Nitruro de Galio) de última generación con una potencia total de hasta 65W, permitiéndote cargar notebooks, tablets, smartphones y accesorios de manera ultrarrápida, eficiente y sin sobrecalentamiento. Gracias a sus 8 puertos de salida (5 USB-C y 3 USB-A), es el accesorio ideal para escritorios de trabajo, mesas de noche, oficinas compartidas o viajes, Tecnología GaN Avanzada, Carga Rápida Power Delivery (PD 65W), 8 Dispositivos en Simultáneo, Gestión Inteligente de Energía, Diseño Versátil con base de apoyo vertical, incluye 1x Cable de alimentación de red eléctrica (220V). Compatibilidad Universal Notebooks / Laptops, Smartphones, Tablets, Gadgets & Varios.","embalaje":null,"imagen":null,"variantes":[],"origen_catalogo":"importacion.xlsx"}') ON CONFLICT DO NOTHING;
