INSERT INTO gm.products (id,source_id,name,description,category_id,packaging_original,primary_image_id,source_record) VALUES ('5e6da5bc-7432-5853-a220-1749670dd509','cable-adaptador-macho-to-jack-3-5mm-hembra-presentado-en-caja-lista-2281','CABLE ADAPTADOR (MACHO) TO JACK 3,5MM (HEMBRA) -  PRESENTADO EN CAJA','Adaptador de audio Lightning a 3,5 mm Hembra, diseñado para conectar auriculares, parlantes y otros dispositivos de audio con ficha 3,5 mm a equipos Apple que cuentan con puerto Lightning. Incorpora un DAC (Convertidor digital-analógico) que permite transformar la señal de audio digital en una señal compatible con auriculares y accesorios de audio tradicionales. Una solución práctica para seguir utilizando tus auriculares con cable en el iPhone, ideal para disfrutar de música, videos, podcasts y llamadas con una conexión estable y de excelente compatibilidad. Su formato compacto facilita el transporte y permite llevarlo siempre junto al dispositivo.','1366e62e-a332-5f85-adff-a04a337c3894',NULL,NULL,'{"id":"cable-adaptador-macho-to-jack-3-5mm-hembra-presentado-en-caja-lista-2281","nombre":"CABLE ADAPTADOR (MACHO) TO JACK 3,5MM (HEMBRA) -  PRESENTADO EN CAJA","categoria":"Cables y Conectores","descripcion":"Adaptador de audio Lightning a 3,5 mm Hembra, diseñado para conectar auriculares, parlantes y otros dispositivos de audio con ficha 3,5 mm a equipos Apple que cuentan con puerto Lightning. Incorpora un DAC (Convertidor digital-analógico) que permite transformar la señal de audio digital en una señal compatible con auriculares y accesorios de audio tradicionales. Una solución práctica para seguir utilizando tus auriculares con cable en el iPhone, ideal para disfrutar de música, videos, podcasts y llamadas con una conexión estable y de excelente compatibilidad. Su formato compacto facilita el transporte y permite llevarlo siempre junto al dispositivo.","embalaje":null,"imagen":null,"variantes":[],"origen_catalogo":"importacion.xlsx"}') ON CONFLICT DO NOTHING;
