INSERT INTO gm.products (id,source_id,name,description,category_id,packaging_original,primary_image_id,source_record) VALUES ('afdd9de6-e317-58e1-98b3-8a1134afee61','cable-mini-plug-mini-plug-3-5-mm-1-8-m-p-audio-pc-notebook-estereos-grueso-lista-1812','CABLE MINI PLUG @ MINI PLUG 3,5 MM 1,8 M P/ AUDIO PC / NOTEBOOK  / ESTEREOS . GRUESO','Cable de audio 3,5 mm a 3,5 mm, ideal para conectar teléfonos, tablets, notebooks, reproductores, equipos de audio, parlantes y otros dispositivos que cuenten con entrada auxiliar. Permite transmitir sonido de manera práctica y estable, ofreciendo una conexión directa para disfrutar de música, videos y contenido multimedia.Su longitud de 1,5 metros brinda comodidad y libertad de movimiento, facilitando la conexión entre dispositivos que se encuentran a cierta distancia. Ideal para utilizar en el hogar, oficina, vehículo o cualquier espacio donde se necesite una conexión de audio mediante ficha auxiliar.','1366e62e-a332-5f85-adff-a04a337c3894',NULL,NULL,'{"id":"cable-mini-plug-mini-plug-3-5-mm-1-8-m-p-audio-pc-notebook-estereos-grueso-lista-1812","nombre":"CABLE MINI PLUG @ MINI PLUG 3,5 MM 1,8 M P/ AUDIO PC / NOTEBOOK  / ESTEREOS . GRUESO","categoria":"Cables y Conectores","descripcion":"Cable de audio 3,5 mm a 3,5 mm, ideal para conectar teléfonos, tablets, notebooks, reproductores, equipos de audio, parlantes y otros dispositivos que cuenten con entrada auxiliar. Permite transmitir sonido de manera práctica y estable, ofreciendo una conexión directa para disfrutar de música, videos y contenido multimedia.Su longitud de 1,5 metros brinda comodidad y libertad de movimiento, facilitando la conexión entre dispositivos que se encuentran a cierta distancia. Ideal para utilizar en el hogar, oficina, vehículo o cualquier espacio donde se necesite una conexión de audio mediante ficha auxiliar.","embalaje":null,"imagen":null,"variantes":[],"origen_catalogo":"importacion.xlsx"}') ON CONFLICT DO NOTHING;
