INSERT INTO gm.products (id,source_id,name,description,category_id,packaging_original,primary_image_id,source_record) VALUES ('2783debf-973c-5880-be6e-c859752d4d4a','adaptador-conversor-hdtv-vga-hdmi-a-vga-con-audio-pc-notebook-proyectores-lista-2366','ADAPTADOR CONVERSOR (HDTV-VGA) HDMI A VGA CON AUDIO  PC / NOTEBOOK / PROYECTORES','Adaptador HDMI a VGA con salida de audio, diseñado para conectar equipos con salida HDMI a monitores, proyectores o pantallas con entrada VGA, incorporando además una salida de audio 3,5 mm para transmitir el sonido de manera independiente.Convierte la señal de video digital HDMI en señal analógica VGA y permite obtener el audio mediante su salida de 3,5 mm, ofreciendo una solución práctica para conectar PC, notebooks, reproductores multimedia, consolas y otros dispositivos HDMI a pantallas VGA con sonido externo. Su diseño compacto facilita la instalación y el transporte, siendo ideal para aplicaciones domésticas, oficinas, presentaciones, aulas y entornos profesionales.','1366e62e-a332-5f85-adff-a04a337c3894',NULL,NULL,'{"id":"adaptador-conversor-hdtv-vga-hdmi-a-vga-con-audio-pc-notebook-proyectores-lista-2366","nombre":"ADAPTADOR CONVERSOR (HDTV-VGA) HDMI A VGA CON AUDIO  PC / NOTEBOOK / PROYECTORES","categoria":"Cables y Conectores","descripcion":"Adaptador HDMI a VGA con salida de audio, diseñado para conectar equipos con salida HDMI a monitores, proyectores o pantallas con entrada VGA, incorporando además una salida de audio 3,5 mm para transmitir el sonido de manera independiente.Convierte la señal de video digital HDMI en señal analógica VGA y permite obtener el audio mediante su salida de 3,5 mm, ofreciendo una solución práctica para conectar PC, notebooks, reproductores multimedia, consolas y otros dispositivos HDMI a pantallas VGA con sonido externo. Su diseño compacto facilita la instalación y el transporte, siendo ideal para aplicaciones domésticas, oficinas, presentaciones, aulas y entornos profesionales.","embalaje":null,"imagen":null,"variantes":[],"origen_catalogo":"importacion.xlsx"}') ON CONFLICT DO NOTHING;
