INSERT INTO gm.products (id,source_id,name,description,category_id,packaging_original,primary_image_id,source_record) VALUES ('d145793c-7dc2-51f4-8292-9ca70dfbb5a9','adaptador-conversor-vga-hdtv-vga-audio-hdmi-pc-notebook-proyectores-lista-2363','ADAPTADOR CONVERSOR ( VGA-HDTV ) VGA + AUDIO @ HDMI  PC / NOTEBOOK / PROYECTORES','Adaptador VGA a HDMI con audio, diseñado para conectar computadoras, notebooks y otros equipos con salida VGA a televisores, monitores, proyectores y pantallas que cuentan con entrada HDMI. Convierte la señal de video analógica VGA en una señal digital HDMI, permitiendo utilizar pantallas modernas con equipos que disponen de una salida VGA. Incorpora entrada de audio para transmitir el sonido junto con la señal de video a través de HDMI, ofreciendo una solución práctica para reproducir contenido multimedia con imagen y sonido en una única conexión. Ideal para PC, notebooks, proyectores, monitores y televisores, tanto en aplicaciones domésticas como profesionales, educativas y de oficina.','1366e62e-a332-5f85-adff-a04a337c3894',NULL,NULL,'{"id":"adaptador-conversor-vga-hdtv-vga-audio-hdmi-pc-notebook-proyectores-lista-2363","nombre":"ADAPTADOR CONVERSOR ( VGA-HDTV ) VGA + AUDIO @ HDMI  PC / NOTEBOOK / PROYECTORES","categoria":"Cables y Conectores","descripcion":"Adaptador VGA a HDMI con audio, diseñado para conectar computadoras, notebooks y otros equipos con salida VGA a televisores, monitores, proyectores y pantallas que cuentan con entrada HDMI. Convierte la señal de video analógica VGA en una señal digital HDMI, permitiendo utilizar pantallas modernas con equipos que disponen de una salida VGA. Incorpora entrada de audio para transmitir el sonido junto con la señal de video a través de HDMI, ofreciendo una solución práctica para reproducir contenido multimedia con imagen y sonido en una única conexión. Ideal para PC, notebooks, proyectores, monitores y televisores, tanto en aplicaciones domésticas como profesionales, educativas y de oficina.","embalaje":null,"imagen":null,"variantes":[],"origen_catalogo":"importacion.xlsx"}') ON CONFLICT DO NOTHING;
